\begin{gathered}
f(x,y)=\tfrac12(x^2+\kappa y^2),\quad\kappa\ge1,\quad\alpha>0,\\
x_k=(1-\alpha)^k x_0,\qquad y_k=(1-\alpha\kappa)^k y_0,\\
